{"implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = {**n, 'children': []}
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            node_map[pid]['children'].append(n['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = set(node_map.keys())
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if nid == 'root':
            continue
        if n['symbol'] in required:
            continue
        children = node_map[nid]['children']
        has_retained_child = any(cid in retained for cid in children)
        if has_retained_child:
            continue
        symbol_set = set()
        for rid in retained:
            if rid != nid:
                symbol_set.add(node_map[rid]['symbol'])
        if required.issubset(symbol_set):
            retained.remove(nid)
            removed.append(nid)
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"}
